class Cluster:
    def __init__(self, l, m, s):
        self.l = l
        self.m = m
        self.s = s

platform = [Cluster(l, m_l, s_l) for l in clusters]

def workload_assign(tasks, platform):
    # LP for fractions
    prob = LpProblem('Assign', LpMinimize)
    f = LpVariable.dicts('f', ((i,l) for i in tasks for l in platform), 0,1)
    prob += lpSum(f[i,l] for i,l)  # or migration cost
    for l in platform:
        prob += lpSum(tasks[i].U * f[i,l] / platform[l].s for i in tasks) <= platform[l].m
    for i in tasks:
        prob += lpSum(f[i,l] for l in platform) == 1
    prob.solve()
    return {i: {l: f[i,l].value() for l in platform} for i in tasks}
